			16);
		assertEquals(BigInteger.ZERO, OP.evaluateBinary(1, 16, BigInteger.ONE, BigInteger.ZERO),
			16);
		assertEquals(BigInteger.ZERO, OP.evaluateBinary(1, 16, BigInteger.ZERO, BigInteger.ONE),
			16);
